'use strict';
document.querySelector('#year').textContent=new Date().getFullYear();
const menu=document.querySelector('.menu'),nav=document.querySelector('header nav');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='☰';}
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰';});
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();});
const dialog=document.querySelector('#detail-dialog'),content=document.querySelector('#detail-content');
const details={
  research:{label:'01 / INSIDE THE RESEARCH LAB',title:'First, the right questions.',text:'Every project starts with understanding. We map your goals, explore your audience, and test ideas before the build begins. A clear direction gives every design and development decision a purpose.',items:['Discovery workshops and project planning','User journeys and content structure','Wireframes and interactive prototypes','A shared brief before design and development']},
  web:{label:'02 / THE BUILD STUDIO',title:'Websites with a point of view.',text:'Your website should feel like your business at its best. We pair a distinctive visual direction with clear navigation and thoughtful development, from a concise company site to a richer editorial experience.',items:['Responsive website design and development','Content management and integrations','Accessible navigation and interaction','Cross-device checks and launch preparation']},
  commerce:{label:'02 / THE BUILD STUDIO',title:'A better place to discover.',text:'Give your products an online home that feels considered from the first visit to the final checkout. We shape shopping experiences around the way your customers browse, compare, and buy.',items:['Storefront design and product discovery','Collections, product pages, and navigation','Cart and checkout integration','A foundation for future improvements']},
  apps:{label:'02 / THE BUILD STUDIO',title:'Make the complex feel simple.',text:'Turn an ambitious idea or a difficult workflow into a tool people can use. We design and develop custom web applications around your goals and the tasks that matter to your users.',items:['Custom applications and business tools','Interface design and interactive prototypes','API and service integrations','Testing, iteration, and ongoing care']},
  fern:{label:'03 / THE PROJECT GALLERY',title:'Fern & Form',text:'A studio concept for a nature-inspired lifestyle store. Calm product discovery, botanical art direction, and clear shopping journeys turn everyday objects into a thoughtful digital experience.',items:['Lifestyle commerce & storefront architecture','Calm, considered product discovery','High-performance checkout integration','Botanical art direction & design system'],previewClass:'fern',previewHTML:'<span>FERN & FORM / OBJECTS WITH INTENTION</span><h3>A little closer<br><em>to nature.</em></h3><p>Considered objects for everyday rituals.</p>'},
  fieldnotes:{label:'03 / THE PROJECT GALLERY',title:'Fieldnotes',text:'A studio concept for independent travel. Editorial destinations, interactive topographical mapping, and immersive storytelling help visitors discover experiences beyond the obvious route.',items:['Editorial destination discovery','Interactive vector mapping & trails','Offline itinerary caching & PWA support','Fluid multimedia storytelling'],previewClass:'travel',previewHTML:'<span>FIELDNOTES / TAKE THE SCENIC ROUTE</span><h3>Somewhere<br><em>less ordinary.</em></h3><p>Discover experiences beyond the expected.</p>'},
  canopy:{label:'03 / THE PROJECT GALLERY',title:'Canopy Core',text:'A real-time environmental telemetry platform tracking canopy temperature, soil moisture, and verified forest carbon metrics through high-frequency sensor networks.',items:['Microclimate sensor telemetry stream','Interactive multi-layer canopy visualizer','Automated carbon offset verification','Low-latency WebSocket data architecture'],previewClass:'canopy',previewHTML:'<span>CANOPY CORE / FOREST TELEMETRY</span><h3>Listening to<br><em>the living canopy.</em></h3><p>Real-time microclimate intelligence & sensor networks.</p>'},
  biome:{label:'03 / THE PROJECT GALLERY',title:'Biome Studio',text:'An in-browser algorithmic design environment translating biological growth algorithms, Voronoi tessellations, and branching geometry into responsive interface components.',items:['GPU-accelerated WebGL shader canvas','Parametric branching component export','Live SVG & CSS token generation','Interactive node-graph workflow'],previewClass:'biome',previewHTML:'<span>BIOME STUDIO / ORGANIC COMPUTATION</span><h3>Code shaped by<br><em>natural growth.</em></h3><p>Parametric branching & generative interface design.</p>'},
  terraform:{label:'03 / THE PROJECT GALLERY',title:'Terraform Audio',text:'A browser-native spatial audio synthesizer and acoustic simulator that models acoustic wave reflections across varied architectural and outdoor environments.',items:['Web Audio API 3D spatial convolution','Interactive acoustic materials simulation','Dynamic binaural head-tracking soundscapes','Low-overhead audio worklet engine'],previewClass:'terraform',previewHTML:'<span>TERRAFORM / SPATIAL SOUND</span><h3>Soundscapes with<br><em>physical presence.</em></h3><p>Binaural room acoustic simulation in the browser.</p>'},
  arbor:{label:'03 / THE PROJECT GALLERY',title:'Arbor Archive',text:'A digital botanical repository archiving rare tree varieties, herbarium pressings, and high-resolution macroscopic cellular scans for researchers and conservationists.',items:['Gigapixel deep-zoom specimen inspection','Faceted phylogenetic taxonomy search','Open botanical API & citation export','Archival color-calibrated imaging'],previewClass:'arbor',previewHTML:'<span>ARBOR ARCHIVE / TAXONOMIC LIBRARY</span><h3>Preserving every<br><em>vein and seed.</em></h3><p>Deep-zoom macroscopic herbarium records.</p>'},
  solaris:{label:'03 / THE PROJECT GALLERY',title:'Solaris Grid',text:'A decentralized solar microgrid operations dashboard showing live generation, storage efficiency, inverter diagnostics, and demand prediction models.',items:['Real-time microgrid telemetry stream','Predictive solar yield ML forecasting','Battery charge & discharge optimization','Clean industrial SVG data charts'],previewClass:'solaris',previewHTML:'<span>SOLARIS GRID / RENEWABLE DISPATCH</span><h3>Power harvested<br><em>from the daylight.</em></h3><p>Decentralized microgrid telemetry & storage analytics.</p>'},
  kinetic:{label:'03 / THE PROJECT GALLERY',title:'Kinetic Atlas',text:'A global interactive 3D geospatial platform visualizing continental avian migration corridors, seasonal jet streams, and oceanic thermal current dynamics.',items:['WebGL 3D spherical globe coordinates','Time-scrubbed migration path replay','Vector wind & ocean current particle shaders','Dense geospatial coordinate compression'],previewClass:'kinetic',previewHTML:'<span>KINETIC ATLAS / CONTINENTAL FLIGHT</span><h3>Mapping journeys<br><em>across the globe.</em></h3><p>Seasonal wildlife migration & climate currents.</p>'},
  tidepool:{label:'03 / THE PROJECT GALLERY',title:'Tidepool Marine',text:'A collaborative coastal marine research tool combining satellite bathymetry, temperature buoy telemetry, and diver reef observation logs into an open dataset.',items:['Bathymetric coastal contour maps','Buoy sensor telemetry & tide forecasting','Crowdsourced reef survey records','Conservation partner data exchange'],previewClass:'tidepool',previewHTML:'<span>TIDEPOOL / COASTAL RESILIENCE</span><h3>Safeguarding the<br><em>coastal margins.</em></h3><p>Living reef monitoring & marine sensor telemetry.</p>'},
  verdant:{label:'03 / THE PROJECT GALLERY',title:'Verdant OS',text:'An eco-conscious web publishing platform engineered for extreme efficiency. Designed to transfer under 80kB per full article while delivering typography of the highest craft.',items:['Carbon budget analytics per pageview','Static-first edge distributed delivery','System-font typographical hierarchy','Zero-dependency reader experience'],previewClass:'verdant',previewHTML:'<span>VERDANT OS / LOW-CARBON WEB</span><h3>Crafted for words.<br><em>Built for efficiency.</em></h3><p>Radically lightweight digital publishing architecture.</p>'}
};
function openDialog(){dialog.showModal();document.body.classList.add('dialog-open');}
function closeDialog(){dialog.close();document.body.classList.remove('dialog-open');}
function addText(tag,text,className){const el=document.createElement(tag);el.textContent=text;if(className)el.className=className;content.append(el);return el;}
document.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>{
  content.replaceChildren();
  if(button.dataset.detail==='contact'){
    content.innerHTML='<div class="eyebrow">04 / LET’S BUILD SOMETHING</div><h2>Tell us your idea.</h2><p>Let’s put your next chapter into words.</p><form id="project-form"><label for="name">Your name</label><input id="name" name="name" placeholder="What should we call you?" autocomplete="name" required><label for="email">Your email</label><input id="email" name="email" type="email" placeholder="you@company.com" autocomplete="email" required><label for="idea">What would you like to create?</label><textarea id="idea" name="idea" rows="3" placeholder="A little about your project…" required></textarea><button class="button" type="submit">Create project brief <span>↗</span></button><p class="form-note">Creates a brief to copy or download. Details stay in your browser.</p><div id="form-result" role="status" hidden></div></form>';
    document.querySelector('#project-form').addEventListener('submit',createBrief);
  }else{
    const detail=details[button.dataset.detail];
    if(!detail)return;
    addText('div',detail.label,'eyebrow');addText('h2',detail.title);addText('p',detail.text);
    if(detail.previewHTML){
      const preview=document.createElement('div');
      preview.className='project-preview '+(detail.previewClass||'');
      preview.innerHTML=detail.previewHTML;
      content.append(preview);
    }
    const list=document.createElement('ul');detail.items.forEach(text=>{const item=document.createElement('li');item.textContent=text;list.append(item);});content.append(list);
    const link=addText('a','Let’s talk about your project ↗','button');link.href='#contact';link.addEventListener('click',closeDialog);
  }
  openDialog();
}));
document.querySelector('.dialog-close').addEventListener('click',closeDialog);dialog.addEventListener('close',()=>document.body.classList.remove('dialog-open'));
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
function createBrief(event){
  event.preventDefault();const data=new FormData(event.currentTarget);const brief=`SPROUT TECH — PROJECT BRIEF\n\nName: ${data.get('name')}\nEmail: ${data.get('email')}\n\nThe idea:\n${data.get('idea')}`;
  const result=document.querySelector('#form-result');result.hidden=false;result.replaceChildren();
  const title=document.createElement('strong');title.textContent='Your next chapter is ready.';const text=document.createElement('p');text.textContent=brief;
  const copy=document.createElement('button');copy.type='button';copy.className='button';copy.textContent='Copy brief';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(brief);copy.textContent='Copied ✓';}catch{copy.textContent='Select the text above to copy';}});
  const download=document.createElement('button');download.type='button';download.className='button';download.textContent='Download brief ↓';download.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([brief],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='sprout-tech-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});result.append(title,text,copy,download);
}
document.querySelector('#watch-film').addEventListener('click',()=>{content.innerHTML='<div class="eyebrow">THE SPROUT TECH CAMPUS / ORIGINAL FILM</div><h2>A place for possibility.</h2><p>Walk from the welcome pavilion to the research lab, build studio, project gallery, and meeting garden.</p><video controls playsinline preload="metadata" src="assets/sprout-campus.mp4"></video><p><a class="film-link" href="assets/sprout-campus.mp4" download>Download the campus film ↓</a></p>';openDialog();});
dialog.addEventListener('close',()=>{content.querySelector('video')?.pause();});
